'use strict';
/* Personal meal choices and spending remain local unless the traveler signs in to private cloud sync. */
let ledgerDay='all',ledgerCategory='all',cloudRevision=null,cloudActive=false,cloudMode='local',cloudPending=false,cloudBusy=false,pendingRemote=null;
const mealDrawerOpen=new Set();
const cloudAvailable=location.protocol==='https:'&&location.hostname==='www.chaoyifan666.fun';
const cloudApi='./api/';
const originalSave=save, originalCard=eventCard, originalDaily=daily, originalKit=kit, originalOverview=overview;
const money=n=>'$'+Number(n||0).toFixed(2);
const mealExpense=id=>(Array.isArray(prefs.expenses)?prefs.expenses:[]).find(x=>x.id==='meal:'+id);
function persist(){originalSave();queueCloudSave();}
save=function(){const ok=originalSave();queueCloudSave();return ok;};
function mapsAddress(address,mode='driving'){return 'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(address)+'&travelmode='+mode;}
function mealPanel(e){
  const group=MEALS[e.id];if(!group)return '';
  const chosen=(prefs.meals&&prefs.meals[e.id])||{},spent=mealExpense(e.id),mode=e.mode||'driving';
  const selected=chosen.name?`<div class="meal-selected"><div><small>已选餐厅</small><strong>${esc(chosen.name)}</strong><span>${spent?`两人实付 ${money(spent.amount)} · `:''}${chosen.rating?`体验 ${'★'.repeat(chosen.rating)} · `:''}${esc(chosen.address||'地址待填')}</span></div>${chosen.address?`<a class="nav-link" href="${esc(mapsAddress(chosen.address,mode))}" target="_blank" rel="noopener noreferrer">↗ 导航</a>`:''}</div>`:'';
  return `<section class="meal-panel meal-panel-compact" aria-label="${esc(group.kind)}餐厅选择">${selected}<details class="meal-drawer" data-meal-drawer="${e.id}" ${mealDrawerOpen.has(e.id)?'open':''}><summary><span class="meal-drawer-symbol" aria-hidden="true">✳</span><span class="meal-drawer-copy"><strong>${esc(group.kind)} · ${chosen.name?'换一家 / 记账点评':'挑一家'} </strong><small>${chosen.name?'已选 '+esc(chosen.name):'3 家候选 · 可自己填饭店'}</small></span><span class="meal-drawer-chevron" aria-hidden="true">⌄</span></summary><div class="meal-drawer-body"><p class="meal-context">${esc(group.context)}</p><div class="meal-options">${group.options.map((o,i)=>`<article class="meal-option ${chosen.name===o.name?'picked':''}"><div class="meal-option-top"><span class="meal-option-num">0${i+1}</span><div><h5>${esc(o.name)}</h5><p>${esc(o.cuisine)}</p></div><span class="meal-score">${esc(o.score)}</span></div><p class="meal-review">${esc(o.review)}</p><div class="meal-meta"><span>约 ${esc(o.price)} / 人*</span><span>${esc(o.fit)}</span></div><div class="meal-option-actions"><button type="button" class="btn ${chosen.name===o.name?'selected-btn':''}" data-pick-meal="${e.id}" data-candidate="${i}">${chosen.name===o.name?'✓ 已选':'选这家'}</button><a href="${esc(mapsAddress(o.address,mode))}" target="_blank" rel="noopener noreferrer">导航 ↗</a><a href="${esc(o.source)}" target="_blank" rel="noopener noreferrer">评价 / 官网 ↗</a></div></article>`).join('')}</div><p class="tiny">* 人均是2026-09-25规划估算，通常未含税、小费与酒；TA 为 Tripadvisor 当时页所示评分，不是实时分数。营业、末单和等位请前一天核对。</p><form class="meal-form" data-meal-form="${e.id}"><div class="form-title"><strong>实际选的 / 最后吃的</strong><span>提前一天填店名，吃完补实付和评价</span></div><div class="meal-form-grid"><label>饭店名字<input name="name" maxlength="120" value="${esc(chosen.name||'')}" placeholder="例如：BirdHouse"></label><label>完整地址 / 地图定位<input name="address" maxlength="250" value="${esc(chosen.address||'')}" placeholder="粘贴街道地址，导航更准"></label><label>两人实付 · USD<input name="spent" type="number" step="0.01" min="0" max="100000" value="${spent?esc(spent.amount):''}" placeholder="吃完再填；自动记入吃饭分类"></label><label>味道体验<select name="rating"><option value="">还没吃 / 不评价</option>${[5,4,3,2,1].map(n=>`<option value="${n}" ${Number(chosen.rating)===n?'selected':''}>${'★'.repeat(n)} · ${['','踩雷','一般','尚可','好吃','很喜欢'][n]}</option>`).join('')}</select></label></div><label>随手评语 / 排队情况<textarea name="note" maxlength="1000" placeholder="值不值得、吃了什么、有什么坑…">${esc(chosen.note||'')}</textarea></label><div class="button-row"><button class="btn primary" type="submit">保存这顿饭 ↗</button>${chosen.address?`<a class="nav-link" href="${esc(mapsAddress(chosen.address,mode))}" target="_blank" rel="noopener noreferrer">打开已填地址的导航</a>`:''}</div></form></div></details></section>`;
}
eventCard=function(d,e){let html=originalCard(d,e);if(e.ticket==='o')html=html.replace(/场次待订单确认|场次已由你核对/g,'已预订 · 21:00').replace('class="tag pending">已预订','class="tag">已预订');if(MEALS[e.id])html=html.replace('</div></article>',mealPanel(e)+'</div></article>').replace('↗ 餐厅导航','↗ 原计划地点');return html;};
function starPanel(i){const s=STARS[i];if(!s)return '';const state=(prefs.starPlans&&prefs.starPlans[i])||{};return `<section class="star-panel"><div class="star-sky"><span class="eyebrow">AFTER DARK / 夜色加映</span><span class="star-orbit">✦ · ✧ · ✦</span><h2>${esc(s.title)}</h2><p>${esc(s.reality)}</p><div class="star-facts"><span>◷ ${esc(s.window)}</span><span>◖ ${esc(s.moon)}</span></div></div><div class="star-body"><div class="star-place"><div><span class="eyebrow">PHOTO SPOT / 正式停车点</span><h3>${esc(s.place)}</h3><p>${esc(s.distance)}</p></div><a class="nav-link" href="${esc(mapsAddress(s.address))}" target="_blank" rel="noopener noreferrer">↗ Google Maps 导航</a></div><div class="star-subjects">${(s.subjects||[]).map(([name,description])=>`<div><strong>${esc(name)}</strong><span>${esc(description)}</span></div>`).join('')}</div><details><summary>今晚怎么拍 · 路线与时间</summary><ol>${s.plan.map(p=>`<li>${esc(p)}</li>`).join('')}</ol></details><details><summary>16mm F1.8 参数 · 从这里起步</summary><p>${esc(s.camera)}</p></details><details><summary>夜间安全与开放规则</summary><p>${esc(s.safety)}</p></details><div class="star-action"><label>这晚状态<select data-star-status="${i}">${[['pending','未决定'],['go','打算去'],['done','拍到了'],['skip','天气 / 体力原因跳过']].map(([v,n])=>`<option value="${v}" ${(state.status||'pending')===v?'selected':''}>${n}</option>`).join('')}</select></label><div>${s.sources.map((u,j)=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">依据 ${j+1} ↗</a>`).join('')}</div></div></div></section>`;}
daily=function(){let html=originalDaily();if(STARS[day])html=html.replace('<div class="notice"><strong>今天最该记住的事',starPanel(day)+'<div class="notice"><strong>今天最该记住的事');return html;};
kit=function(){return originalKit().replace('本页输入只存在当前设备的浏览器；不会上传、不会自动跨设备同步。','未登录私有云时仅保存在本机；登录后个人记录可在设备间同步。不要填写门锁密码、卡号或证件号。').replace('<div class="kit-grid">',cloudPanel()+'<div class="kit-grid">').replace(/<label><input type="checkbox" data-confirm="o"[^>]*> 已核对：10\/3 21:00 O 秀<\/label>/,'<div class="booking-confirmed">✓ 已预订 · 10/3 21:00 Bellagio O 秀。电子票与座位号请离线保存。</div>').replace('勾选表示你确认了场次，不会向商家预订。若时间不同，应重新调整相关行程，不要只改一张票的标签。','Ken’s 的勾选只表示你对照了订单；不会代替预订。').replace('例：周五20:50首次进闸 → 周六20:50到期。','例：周六09:10首次进闸 → 周日09:10到期。').replace('（仅本机）','（登录后可同步）').replace('保存到这台设备','保存个人记录').replace('本次核验：2026.09.20','餐厅与观星补充核验：2026.09.25');};
overview=function(){return originalOverview().replace('进度仅保存在当前浏览器','进度可本机保存，登录后私有云同步').replace('O 秀21:00、Ken’s16:00仍需要票券核对','O 秀10/3 21:00已预订；Ken’s 10/5 16:00请对照电子票核对');};
function allExpenses(){return Array.isArray(prefs.expenses)?prefs.expenses.filter(x=>x&&Number.isFinite(Number(x.amount))&&Number(x.amount)>=0):[];}
function expenseRows(){const rows=allExpenses().filter(x=>(ledgerDay==='all'||x.date===ledgerDay)&&(ledgerCategory==='all'||x.category===ledgerCategory)).sort((a,b)=>b.date.localeCompare(a.date));if(!rows.length)return '<div class="empty">还没有符合筛选条件的消费。吃饭在每日餐卡填实付，也会自动进这里。</div>';return rows.map(x=>`<article class="expense-row"><span class="expense-icon">${{food:'✳',fuel:'⛽',supplies:'▣',tickets:'◇',souvenirs:'✦',lodging:'⌂',transport:'↗',other:'·'}[x.category]||'·'}</span><div class="expense-info"><strong>${esc(x.title)}</strong><span>${esc(x.date)} · ${esc(EXPENSE_CATEGORIES[x.category]||'其他')}${x.note?' · '+esc(x.note):''}</span></div><div class="expense-right"><strong>${money(x.amount)}</strong><div><button type="button" data-edit-expense="${esc(x.id)}">编辑</button><button type="button" data-delete-expense="${esc(x.id)}">删除</button></div></div></article>`).join('');}
function cloudPanel(){const state={local:'仅本机 · 尚未登录',empty:'云端为空 · 等待你决定是否上传本机记录',choose:'本机和云端都有记录 · 请选保留哪一份',syncing:'正在同步…',synced:'云端已同步',offline:'网络不可用 · 已留在本机',conflict:'其他设备保存了新版本 · 请先备份再重新读取'}[cloudMode];return `<section class="cloud-panel"><div><span class="eyebrow">PRIVATE CLOUD / 私有旅途记录</span><h2>${esc(state)}</h2><p>公开网页只放行程与候选；餐厅决定、实付、评语、民宿地址保存在本机，登录后也存到你的阿里云 MySQL。不要填门锁密码、银行卡或证件号。</p></div>${!cloudAvailable?'<p class="tiny">此预览 / 离线版没有云端接口；个人记录仍可本机使用。</p>':cloudMode==='local'?'<form id="cloud-login"><label>旅途密码<input type="password" name="password" required autocomplete="current-password" placeholder="输入私有旅途密码"></label><button class="btn primary" type="submit">登录并读取云端</button></form>':`<div class="cloud-actions">${cloudMode==='empty'?'<button class="btn primary" data-action="upload-local">将本机记录上传云端</button>':''}${cloudMode==='choose'?'<button class="btn primary" data-action="choose-remote">备份本机后使用云端</button><button class="btn" data-action="choose-local">用本机记录覆盖云端</button>':''}${cloudMode==='offline'?'<button class="btn" data-action="retry-cloud">重试同步</button>':''}${['offline','conflict'].includes(cloudMode)?'<button class="btn" data-action="reload-cloud">备份本机后读取云端</button>':''}<button class="btn" data-action="cloud-logout">退出云端并清除本机个人记录</button></div>`}</section>`;}
function ledger(){const expenses=allExpenses(),total=expenses.reduce((n,x)=>n+Number(x.amount),0),food=expenses.filter(x=>x.category==='food').reduce((n,x)=>n+Number(x.amount),0),logged=Object.keys(prefs.meals||{}).length;return `<div class="page-heading ledger-heading"><div><p class="eyebrow">THE LITTLE THINGS ADD UP</p><h1>旅途账本，<em>记得刚刚好。</em></h1><p>每顿饭从候选中选，吃完记实际感受与花费；其他消费按类别补上。金额都是 USD 实付，不与信用卡返现混算。</p></div></div>${cloudPanel()}<section class="ledger-summary"><div><span>这趟已记录</span><strong>${money(total)}</strong><small>${expenses.length} 笔消费</small></div><div><span>其中吃饭</span><strong>${money(food)}</strong><small>${logged} 顿已选餐厅</small></div><div><span>六天行程</span><strong>${DAYS.length} DAYS</strong><small>可按日筛选核对</small></div></section><section class="category-grid">${Object.entries(EXPENSE_CATEGORIES).map(([k,n])=>`<button class="category-chip ${ledgerCategory===k?'active':''}" data-ledger-category="${k}"><span>${esc(n)}</span><strong>${money(expenses.filter(x=>x.category===k).reduce((a,x)=>a+Number(x.amount),0))}</strong></button>`).join('')}</section><div class="ledger-layout"><section class="panel ledger-list"><div class="section-title"><h2>每一笔，都能找回来。</h2><p>餐费可在每日餐卡编辑；其他项目点右侧“编辑”。</p></div><div class="ledger-filters"><label>日期<select id="ledger-day"><option value="all">全部日期</option>${DAYS.map(d=>`<option value="${d.date}" ${ledgerDay===d.date?'selected':''}>${d.short} ${d.weekday}</option>`).join('')}</select></label><label>分类<select id="ledger-category"><option value="all">全部类别</option>${Object.entries(EXPENSE_CATEGORIES).map(([k,n])=>`<option value="${k}" ${ledgerCategory===k?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="expense-list">${expenseRows()}</div></section><section class="panel ledger-editor"><p class="eyebrow">ADD A MEMORY / 也记一笔</p><h2>新增消费</h2><form id="expense-form"><input type="hidden" name="id"><label>日期<select name="date" required>${DAYS.map(d=>`<option value="${d.date}" ${d.index===day?'selected':''}>${d.short} ${d.weekday}</option>`).join('')}</select></label><label>分类<select name="category" required>${Object.entries(EXPENSE_CATEGORIES).map(([k,n])=>`<option value="${k}">${n}</option>`).join('')}</select></label><label>商家 / 用途<input name="title" required maxlength="120" placeholder="例如：加油站、纪念品店"></label><label>实际花费 · USD<input name="amount" type="number" required min="0.01" max="100000" step="0.01" placeholder="0.00"></label><label>备注<textarea name="note" maxlength="500" placeholder="记下付款方式、几个人分摊等；不要填卡号"></textarea></label><div class="button-row"><button class="btn primary" type="submit">保存这笔消费</button><button class="btn" type="reset">清空</button></div></form><p class="tiny">本页不连接银行卡，也不自动抓取账单；只记录你输入的真实金额。离线时保存在当前浏览器，登录后自动同步。</p></section></div>`;}
async function api(method,path,body){const response=await fetch(cloudApi+path,{method,credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-Guide-Request':'1'},body:body===undefined?undefined:JSON.stringify(body)});let data={};try{data=await response.json();}catch{}return {response,data};}
function queueCloudSave(){if(!cloudActive||!cloudAvailable||cloudRevision===null)return;cloudPending=true;if(!cloudBusy)flushCloud();}
async function flushCloud(){if(cloudBusy||!cloudActive)return;cloudBusy=true;while(cloudPending&&cloudActive){cloudPending=false;cloudMode='syncing';const snapshot=structuredClone(prefs);try{const {response,data}=await api('PUT','state',{revision:cloudRevision,state:snapshot});if(response.ok){cloudRevision=data.revision;cloudMode='synced';}else if(response.status===409){cloudMode='conflict';cloudActive=false;toast('云端有更新，未覆盖其他设备。请先导出本机备份，再读取云端。');break;}else if(response.status===401||response.status===403){cloudMode='local';cloudActive=false;toast('云端登录已过期，本机记录保留。');break;}else throw Error(data.error||'save failed');}catch{cloudMode='offline';cloudPending=true;break;}}cloudBusy=false;if(view==='ledger'||view==='kit')render();}
const personalPart=s=>({done:s.done||{},packed:s.packed||{},confirmed:s.confirmed||{},airbnb:s.airbnb||'',note:s.note||'',railStart:s.railStart||'',meals:s.meals||{},expenses:s.expenses||[],starPlans:s.starPlans||{}});
const hasPersonal=s=>{const p=personalPart(s);return Object.values(p).some(v=>typeof v==='string'?v.trim():Array.isArray(v)?v.length:Object.keys(v).length);};
async function fetchCloudState(){if(!cloudAvailable)return;try{const {response,data}=await api('GET','state');if(!response.ok){cloudMode='local';return;}cloudRevision=data.revision;const remote=data.state||{};if(hasPersonal(remote)){if(hasPersonal(prefs)&&JSON.stringify(personalPart(prefs))!==JSON.stringify(personalPart(remote))){pendingRemote=remote;cloudActive=false;cloudMode='choose';}else{prefs={...structuredClone(initial),...remote};originalSave();cloudActive=true;cloudMode='synced';}}else{cloudActive=false;cloudMode='empty';}render();}catch{if(cloudRevision!==null)cloudMode='offline';}}
async function loginCloud(password){const {response,data}=await api('POST','login',{password});if(!response.ok)throw Error(data.error||'登录失败');await fetchCloudState();}
function rerenderKeepingScroll(){const pos=window.scrollY;render();window.scrollTo(0,pos);}
document.addEventListener('submit',async e=>{if(e.target.id==='cloud-login'){e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;try{await loginCloud(e.target.elements.password.value);toast('已登录。请确认云端或本机记录。');}catch(err){toast('登录失败：'+err.message);}finally{btn.disabled=false;}return;}
  if(e.target.dataset.mealForm){e.preventDefault();const id=e.target.dataset.mealForm,form=e.target,name=form.elements.name.value.trim(),address=form.elements.address.value.trim(),rating=form.elements.rating.value,note=form.elements.note.value.trim(),spent=form.elements.spent.value.trim();if(!name||!address){toast('请填写饭店名字和地址，才能准确导航。');return;}if(spent&&(!Number.isFinite(Number(spent))||Number(spent)<0||Number(spent)>100000)){toast('实付金额不正确。');return;}prefs.meals=prefs.meals||{};prefs.meals[id]={name:name.slice(0,120),address:address.slice(0,250),rating:rating?Number(rating):null,note:note.slice(0,1000)};prefs.expenses=allExpenses().filter(x=>x.id!=='meal:'+id);if(spent&&Number(spent)>0){const dayIndex=Number(id.match(/^d(\d+)-/)?.[1]);prefs.expenses.push({id:'meal:'+id,date:DAYS[dayIndex].date,category:'food',title:name.slice(0,120),amount:Number(spent),note:'每日餐卡自动记录'});}save();toast('这顿饭已记下，实付已同步到账本。');rerenderKeepingScroll();return;}
  if(e.target.getAttribute('id')==='expense-form'){e.preventDefault();const f=e.target.elements,id=f.namedItem('id').value||('expense:'+Date.now()+':'+Math.random().toString(36).slice(2)),amount=Number(f.namedItem('amount').value);if(!Number.isFinite(amount)||amount<=0||amount>100000){toast('请输入有效的美元金额。');return;}const row={id,date:f.namedItem('date').value,category:f.namedItem('category').value,title:f.namedItem('title').value.trim().slice(0,120),amount,note:f.namedItem('note').value.trim().slice(0,500)};if(!row.title||!DAYS.some(d=>d.date===row.date)||!EXPENSE_CATEGORIES[row.category]){toast('请核对日期、类别和用途。');return;}prefs.expenses=allExpenses().filter(x=>x.id!==id);prefs.expenses.push(row);save();toast('消费已记录。');rerenderKeepingScroll();return;}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.pickMeal){const id=b.dataset.pickMeal,o=MEALS[id]?.options[Number(b.dataset.candidate)];if(!o)return;mealDrawerOpen.add(id);prefs.meals=prefs.meals||{};prefs.meals[id]={...(prefs.meals[id]||{}),name:o.name,address:o.address};save();toast('已选 '+o.name+'；吃完可以补味道和实付。');rerenderKeepingScroll();return;}
  if(b.dataset.ledgerCategory){ledgerCategory=b.dataset.ledgerCategory===ledgerCategory?'all':b.dataset.ledgerCategory;render();return;}
  if(b.dataset.editExpense){const x=allExpenses().find(y=>y.id===b.dataset.editExpense);if(!x)return;if(x.id.startsWith('meal:')){const id=x.id.slice(5),di=Number(id.match(/^d(\d+)-/)?.[1]);chooseDay(di);setTimeout(()=>document.getElementById(id)?.scrollIntoView({behavior:'smooth'}),50);return;}const f=$('#expense-form').elements;for(const [k,v] of Object.entries({id:x.id,date:x.date,category:x.category,title:x.title,amount:x.amount,note:x.note||''}))f.namedItem(k).value=v;$('#expense-form').scrollIntoView({behavior:'smooth',block:'center'});return;}
  if(b.dataset.deleteExpense){const id=b.dataset.deleteExpense;if(!confirm('确定删除这笔消费吗？'))return;prefs.expenses=allExpenses().filter(x=>x.id!==id);save();render();toast('已删除这笔消费。');return;}
  if(b.dataset.action==='upload-local'){cloudActive=true;cloudMode='syncing';queueCloudSave();render();return;}
  if(b.dataset.action==='choose-remote'){if(!pendingRemote)return;download('canyon-west-before-cloud-merge.json',JSON.stringify({version:2,prefs},null,2),'application/json');prefs={...structuredClone(initial),...pendingRemote};pendingRemote=null;originalSave();cloudActive=true;cloudMode='synced';render();toast('已使用云端记录，本机旧记录已下载为备份。');return;}
  if(b.dataset.action==='choose-local'){if(!pendingRemote||!confirm('确定用这台设备的记录覆盖云端吗？网页会先下载云端旧记录备份。'))return;download('canyon-west-cloud-before-overwrite.json',JSON.stringify({version:2,prefs:pendingRemote},null,2),'application/json');pendingRemote=null;cloudActive=true;cloudMode='syncing';queueCloudSave();render();return;}
  if(b.dataset.action==='retry-cloud'){cloudActive=true;cloudPending=true;flushCloud();render();return;}
  if(b.dataset.action==='reload-cloud'){if(!confirm('确定读取云端并替换当前记录吗？网页会先下载本机备份。'))return;download('canyon-west-local-before-reload.json',JSON.stringify({version:2,prefs},null,2),'application/json');cloudActive=false;try{const {response,data}=await api('GET','state');if(!response.ok)throw Error('读取失败');prefs={...structuredClone(initial),...(data.state||{})};cloudRevision=data.revision;pendingRemote=null;originalSave();cloudActive=true;cloudMode='synced';render();toast('已重新读取云端；本机旧记录已下载为备份。');}catch{cloudMode='offline';render();toast('云端读取失败，原本机记录仍在。');}return;}
  if(b.dataset.action==='cloud-logout'){await api('POST','logout',{}).catch(()=>{});cloudActive=false;cloudRevision=null;cloudMode='local';pendingRemote=null;prefs=structuredClone(initial);localStorage.removeItem(KEY);render();toast('已退出，并清除这台设备上的个人记录。');return;}});
document.addEventListener('change',e=>{if(e.target.id==='ledger-day'){ledgerDay=e.target.value;render();}if(e.target.id==='ledger-category'){ledgerCategory=e.target.value;render();}if(e.target.dataset.starStatus!==undefined){const i=e.target.dataset.starStatus;prefs.starPlans=prefs.starPlans||{};prefs.starPlans[i]={status:e.target.value};save();toast('观星安排已记录。');}});
document.addEventListener('toggle',e=>{const drawer=e.target;if(drawer.matches?.('details[data-meal-drawer]')&&drawer.isConnected){if(drawer.open)mealDrawerOpen.add(drawer.dataset.mealDrawer);else mealDrawerOpen.delete(drawer.dataset.mealDrawer);}},true);
document.addEventListener('DOMContentLoaded',()=>{if(cloudAvailable)fetchCloudState();});
